def insertion_point(xs, x):
    """Leftmost index to insert x into sorted xs (bisect_left)."""
    lo, hi = 0, len(xs)
    while lo < hi:
        mid = (lo + hi) // 2
        if xs[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    return lo
